def jendela(daftar, k):
    for i in range(len(daftar) - k + 1):
        yield daftar[i:i + k]

from itertools import islice

def prima():
    ditemukan = []
    n = 2
    while True:
        if all(n % p != 0 for p in ditemukan if p * p <= n):
            ditemukan.append(n)
            yield n
        n += 1

def n_prima_pertama(n):
    return list(islice(prima(), n))

